CREATE TRIGGER calendar_disconnect_snapshot_insert BEFORE INSERT ON calendar_snapshot WHEN EXISTS (SELECT 1 FROM calendar_account_disconnect WHERE person_id = NEW.person_id AND account_id = NEW.account_id) BEGIN SELECT RAISE(IGNORE); END;
CREATE TRIGGER calendar_disconnect_snapshot_update BEFORE UPDATE ON calendar_snapshot WHEN EXISTS (SELECT 1 FROM calendar_account_disconnect WHERE person_id = NEW.person_id AND account_id = NEW.account_id) BEGIN SELECT RAISE(IGNORE); END;
CREATE TRIGGER calendar_disconnect_range_insert BEFORE INSERT ON calendar_range WHEN EXISTS (SELECT 1 FROM calendar_account_disconnect WHERE person_id = NEW.person_id AND account_id = NEW.account_id) BEGIN SELECT RAISE(IGNORE); END;
CREATE TRIGGER calendar_disconnect_range_update BEFORE UPDATE ON calendar_range WHEN EXISTS (SELECT 1 FROM calendar_account_disconnect WHERE person_id = NEW.person_id AND account_id = NEW.account_id) BEGIN SELECT RAISE(IGNORE); END;
CREATE TRIGGER calendar_disconnect_channel_insert BEFORE INSERT ON google_push_channel WHEN EXISTS (SELECT 1 FROM calendar_account_disconnect WHERE person_id = NEW.person_id AND account_id = NEW.account_id) BEGIN SELECT RAISE(ABORT, 'Account disconnection prevents new channels'); END;
